/**
 * The kit's reference, one entry per function an agent or engineer calls:
 * what it does, its signature (what `kitDeclarations()` emits), and a
 * complete script that uses it. `d15-kit-reference` fails when a kit
 * function has no entry, an entry has no example, or an example doesn't
 * pass the kit's source check, type-check against the declarations, or run.
 *
 * A kit file that adds a function adds its entry here in the same change.
 */

export interface KitEntry {
  /** As a script writes it: `routes.along`, `ctx.edit`, `PartBuilder.box`. */
  readonly name: string;
  readonly summary: string;
  /** TypeScript, as declared for script authors (shared types: `KIT_PRELUDE`). */
  readonly signature: string;
  /** A complete script using it (imports only @permitzip/bim-script). */
  readonly example: string;
  /** Words people search with ("rooftop unit", "drain slope"). */
  readonly topics: readonly string[];
}

/** A worked task: which entries, in which order, and the script shape. */
export interface KitRecipe {
  readonly name: string;
  /** The job as an engineer names it ("sheets", "pipe routing"); the reference's task index. */
  readonly task: string;
  readonly summary: string;
  readonly steps: readonly string[];
  readonly uses: readonly string[];
  readonly topics: readonly string[];
  /** A complete script for the task (imports only @permitzip/bim-script). */
  readonly example: string;
  /** Runs only on a model that already has what it names (a saved part type, a placed unit). */
  readonly needsModelContent?: boolean;
}

const KIT = 'import { defineScript, units, routes, parts, building, equipment, documents, markups, drafting, checks, electrical } from "@permitzip/bim-script";';

const layout = (body: string, reads = "{ levels: true }") => `${KIT}\nexport default defineScript({\n  kind: "layout",\n  reads: ${reads},\n  parameters: {},\n  run(ctx) {\n${body}\n  },\n});\n`;
const route = (body: string) => `${KIT}\nexport default defineScript({\n  kind: "route",\n  reads: { levels: true },\n  parameters: {},\n  run(ctx) {\n${body}\n  },\n});\n`;
const part = (body: string) => `${KIT}\nexport default defineScript({\n  kind: "part",\n  reads: {},\n  parameters: { width: { type: "quantity", kind: "length", unit: "in", label: "Width", default: units.in(24) } },\n  run(ctx, v) {\n${body}\n  },\n});\n`;

const WALLS = `    const walls = building.walls(ctx, { level: "L1", points: [{ x: units.ft(0), y: units.ft(0) }, { x: units.ft(30), y: units.ft(0) }, { x: units.ft(30), y: units.ft(20) }, { x: units.ft(0), y: units.ft(20) }], closed: true, thickness: units.in(8), height: units.ft(10) });`;
const PLAN = `    const plan = documents.planView(ctx, { level: "L1", name: "Level 1 - Plan", scale: 48 });`;
const DRAIN = `    const drain = ctx.calc({ calc: "plumbing.size_drain", inputs: { role: "building_drain", dfu: 88, slope_in_per_ft: 0.125, serves_water_closet: true }, plumbingEdition: "2021" });\n    if (!drain.ok) throw new Error(drain.reason);\n    const size = Number(drain.run.values.find((v) => v.key === "size_in")?.value);\n    ctx.label(\`Building drain, \${size} in at 1/8 in per ft\`);\n    routes.along(ctx, { level: "L1", domain: "pipe", size: routes.pipe(units.in(size), "pvc"), system: { id: "san-1", kind: "sanitary" }, height: units.ft(1), slope: { rise: units.in(0.125), per: units.ft(1) }, flow: "with_points", points: [{ x: units.ft(0), y: units.ft(5) }, { x: units.ft(40), y: units.ft(5) }] });`;
const BOX = `    const b = parts.part("Box", { type: "24", category: "generic" });\n    b.box({ length: v.width, width: units.in(12), height: units.in(12) });`;


const EDGE = (x0: number, x1: number) => `[{ x: units.ft(${x0}), y: units.ft(0) }, { x: units.ft(${x1}), y: units.ft(0) }, { x: units.ft(${x1}), y: units.ft(14) }, { x: units.ft(${x0}), y: units.ft(14) }]`;
const UNIT = `    building.walls(ctx, { level: "L1", points: ${EDGE(0, 32)}, closed: true, thickness: units.in(6), height: units.ft(9) });\n    building.walls(ctx, { level: "L1", points: [{ x: units.ft(14), y: units.ft(0) }, { x: units.ft(14), y: units.ft(14) }], thickness: units.in(4), height: units.ft(9) });\n    const bedroom = building.room(ctx, { level: "L1", number: "101", name: "Bedroom", outline: ${EDGE(0, 14)} });\n    const living = building.room(ctx, { level: "L1", number: "102", name: "Living room", outline: ${EDGE(14, 32)} });`;
const RECEPTACLES = `    const proposal = ctx.propose("electrical.receptacles", { typeId: "builtin:duplex-receptacle@1", roomIds: [bedroom, living], options: { mode: "dwelling", edition: "2023" } });\n    ctx.acceptGhosts(proposal.ghosts, proposal.summary);`;
const PANEL = `    equipment.place(ctx, { level: "L1", type: "builtin:panelboard-125-208-1ph@1", at: { x: units.ft(1), y: units.ft(13) }, mark: "LP-1" });`;
const TEMPLATE = `    ctx.edit({ type: "save_catalog_entry", entry: { type: "circuit_template", name: "Dwelling unit", description: "Bedroom and living room receptacles", rules: [{ room: "bedroom", devices: "receptacles" }, { room: "living", devices: "receptacles" }] } });\n    const circuits = ctx.read<{ command: unknown; message: string }>("electrical.circuit_template_plan", { template: "Dwelling unit", units: [{ panel: "LP-1", rooms: ["101", "102"] }] });\n    ctx.editSteps(circuits.command);`;
const CIRCUITED = `${UNIT}\n${PANEL}\n${RECEPTACLES}\n${TEMPLATE}`;
const DUCTS = `    const plan = documents.planView(ctx, { level: "L1", name: "Level 1 - Mechanical", scale: 48, cutHeight: units.ft(10) });\n    routes.along(ctx, { level: "L1", domain: "duct", size: routes.rect(units.in(20), units.in(12)), system: { id: "sa-1", kind: "supply_air" }, height: units.ft(9), points: [{ x: units.ft(2), y: units.ft(10) }, { x: units.ft(28), y: units.ft(10) }] });\n    routes.along(ctx, { level: "L1", domain: "duct", size: routes.rect(units.in(20), units.in(12)), system: { id: "ra-1", kind: "return_air" }, height: units.ft(9), points: [{ x: units.ft(15), y: units.ft(2) }, { x: units.ft(15), y: units.ft(18) }] });`;
const ROOF = `    ctx.edit({ type: "create_level", levelId: ctx.id("level"), name: "Roof", elevationMm: 9000 });`;
const RUNS = '{ levels: true, kinds: ["run_segment"] }';

